[
  {
    "statement": "IF tool_name ∈ ALWAYS_ALLOWED_TOOLS THEN policy returns (True, \"Allowed: {tool_name} is a read‑only or safe action.\")"
  },
  {
    "statement": "IF tool_name = \"add_to_blacklist\" AND verify_police_notice_success = True AND verify_police_notice_entity_id = entity_id AND analyze_association_success = True AND analyze_association_entity_id = entity_id AND query_blacklist_status_success = True AND query_blacklist_status_entity_id = entity_id AND query_blacklist_status_blacklisted = False THEN policy returns (True, \"Allowed: all required verifications present for add_to_blacklist.\")"
  },
  {
    "statement": "IF tool_name = \"add_to_blacklist\" AND (verify_police_notice_success = False OR verify_police_notice_entity_id ≠ entity_id) THEN policy returns (False, \"Denied: successful verify_police_notice for this entity is required.\")"
  },
  {
    "statement": "IF tool_name = \"add_to_blacklist\" AND (analyze_association_success = False OR analyze_association_entity_id ≠ entity_id) THEN policy returns (False, \"Denied: successful analyze_association for this entity is required.\")"
  },
  {
    "statement": "IF tool_name = \"add_to_blacklist\" AND (query_blacklist_status_success = False OR query_blacklist_status_entity_id ≠ entity_id) THEN policy returns (False, \"Denied: missing query_blacklist_status result for this entity.\")"
  },
  {
    "statement": "IF tool_name = \"add_to_blacklist\" AND query_blacklist_status_blacklisted = True THEN policy returns (False, \"Denied: entity is already blacklisted.\")"
  },
  {
