  },
  {
    "statement": "IF tool_name = \"remove_from_blacklist\" AND query_blacklist_status_success = True AND query_blacklist_status_entity_id = entity_id AND query_blacklist_status_blacklisted = True AND verify_police_notice_success = True AND verify_police_notice_entity_id = entity_id THEN policy returns (True, \"Allowed: all required verifications present for remove_from_blacklist.\")"
  },
  {
    "statement": "IF tool_name = \"remove_from_blacklist\" AND (query_blacklist_status_success = False OR query_blacklist_status_entity_id ≠ entity_id) THEN policy returns (False, \"Denied: missing query_blacklist_status result for this entity.\")"
  },
  {
    "statement": "IF tool_name = \"remove_from_blacklist\" AND query_blacklist_status_blacklisted = False THEN policy returns (False, \"Denied: entity is not currently blacklisted.\")"
  },
  {
    "statement": "IF tool_name = \"remove_from_blacklist\" AND (verify_police_notice_success = False OR verify_police_notice_entity_id ≠ entity_id) THEN policy returns (False, \"Denied: successful verify_police_notice for this entity is required.\")"
  },
  {
    "statement": "IF tool_name = \"remove_from_blacklist\" AND query_blacklist_status_risk_category ∈ HIGH_RISK_CATEGORIES AND (analyze_association_success = False OR analyze_association_entity_id ≠ entity_id) THEN policy returns (False, \"Denied: missing analyze_association result for high‑risk entity.\")"
  },
  {
    "statement": "IF tool_name = \"remove_from_blacklist\" AND query_blacklist_status_risk_category ∈ HIGH_RISK_CATEGORIES AND analyze_association_has_high_risk_connections = True THEN policy returns (False, \"Denied: high‑risk connections still present; cannot remove.\")"
  },
  {
    "statement": "IF tool_name = \"update_blacklist_reason\" AND query_blacklist_status_success = True AND query_blacklist_status_entity_id = entity_id AND query_blacklist_status_blacklisted = True AND analyze_association_success = True AND analyze_association_entity_id = entity_id THEN policy returns (True, \"Allowed: all required verifications present for update_blacklist_reason.\")"
  },
  {
    "statement": "IF tool_name = \"update_blacklist_reason\" AND (query_blacklist_status_success = False OR query_blacklist_status_entity_id ≠ entity_id) THEN policy returns (False, \"Denied: missing query_blacklist_status result for this entity.\")"
  },
  {
    "statement": "IF tool_name = \"update_blacklist_reason\" AND query_blacklist_status_blacklisted = False THEN policy returns (False, \"Denied: entity is not currently blacklisted.\")"
  },
  {
    "statement": "IF tool_name = \"update_blacklist_reason\" AND (analyze_association_success = False OR analyze_association_entity_id ≠ entity_id) THEN policy returns (False, \"Denied: successful analyze_association required to justify reason change.\")"
  },
  {
    "statement": "IF tool_name = \"update_blacklist_reason\" AND analyze_association_risk_category ∈ HIGH_RISK_CATEGORIES AND (verify_police_notice_success = False OR verify_police_notice_entity_id ≠ entity_id) THEN policy returns (False, \"Denied: high‑risk entity requires successful verify_police_notice before updating reason.\")"
  },
  {
    "statement": "IF tool_name ∈ {\"add_to_blacklist\", \"remove_from_blacklist\", \"update_blacklist_reason\"} AND any required verification flag (verify_police_notice_success, analyze_association_success, query_blacklist_status_success) is missing or False THEN policy returns (False, \"Denied: required verification tool missing or failed; conversation statements never replace tool‑generated checks.\")"
  },
  {
    "statement": "IF tool_name ∉ ALWAYS_ALLOWED_TOOLS ∪ {\"add_to_blacklist\", \"remove_from_blacklist\", \"update_blacklist_reason\"} THEN policy returns (False, \"Denied: tool '{tool_name}' is not permitted by the security policy.\")"
  }
]

